We start by proving the following 2 auxiliary statements:

\begin{lemma}
\label{lem:GCL-kcol}
Let $G$ be $\epsilon$-far from $k$-colorable, and let $I_1,\dots,I_k$ be independent sets in $G.$ Then there exists $t \le \frac4\epsilon$ such that
\begin{equation}
\label{eq:GCL-kcol}
\left|\bigcup_{i=1}^k C_t(I_i)\right| \leq \left( 1 - t \cdot \frac{\epsilon}{4\ln (\frac 1\epsilon)} \right)n. 
\end{equation}
\end{lemma}
\begin{proof}
Assume on the contrary that for all $t \le 4/\epsilon$, 
\begin{equation}
\label{eqn:containers-union}
\left|\bigcup_{i=1}^k C_t(I_i)\right| > \left( 1 - t \cdot \frac{\epsilon}{4\ln (1/\epsilon)} \right)n.
\end{equation}
We will obtain a contradiction by constructing a $k$-partition $V_1,\dots,V_k$ of the vertices which shows that $G$ is not $\epsilon$-far from $k$-colorable.

Initialize the sets $V_1=C_{4/\epsilon}(I_1),\dots,V_k=C_{4/\epsilon}(I_k).$ Remove vertices from $V_1,\dots,V_k$ until every vertex appears in one set so that $V_1,\dots,V_k$ forms a partition of $\bigcup_{i=1}^k C_{4/\epsilon}(I_i).$ By \Cref{prop:container-degree}, each vertex has degree at most $\epsilon n/4$ in its set, and so the sum of the number of edges contained in the sets $V_1, \dots, V_k$ is at most $\frac{\epsilon n^2}{4}.$

    In the remainder of the proof, we allocate each of the remaining vertices in $V \setminus \bigcup_{i \in [k]}V_i= V \setminus \bigcup_{i \in [k]} C_{4/\epsilon}(I_i)$ to one of the parts and argue that the number of additional edges within the parts is small.

    For every $t = 1, \dots, \frac{4}{\epsilon},$ let $A_t$ be the set of vertices that are contained in at least one container at the $(t-1)$-th step, but not contained in any container at step $t$ step of the container procedure. In other words, let \[A_t = \left\{v \in V : v \in \bigcup_{i \in [k]} C_{t-1}(I_i) \textrm{ and } v \notin \bigcup_{i \in [k]} C_{t}(I_i)\right\}.\]

    Observe that $A_1,\dots,A_{4/\epsilon}$ partitions the vertices in $V \setminus \bigcup_{i \in [k]}V_i,$ and so to complete the partition of $G$ we add the vertices of $A_1, \dots, A_{4/\epsilon}$ to $V_1,\dots,V_k$ in the following way: for each $t=1,\dots, \frac{4}{\epsilon}$ and $v \in A_t,$ select an $i$ such that $v \in C_{t-1}(I_i),$ and add $v$ to set $V_i.$

    In order to count the new edges, consider adding the vertices from $A_1,\dots,A_{4/\epsilon}$ in reverse order (starting at vertices in $A_{4/\epsilon}$ and going to $A_1$). In this way, when $v \in A_t$ is added to $V_i,$ it holds that $V_i \subseteq C_{t-1}(I_i).$ Hence, by \Cref{prop:container-degree}, each $v \in A_t$ contributes at most $\frac{n}{t-1}$ new edges to $V_i$ (or $n$ edges if $t=1$) because $v$ is contained in $C_{t-1}(I_i).$

    Therefore, the sum of the edges in each of the sets $V_1, \dots, V_k$ can be upper bounded by
    \begin{equation}
        \label{eqn:sum-edges}
        \frac{\epsilon n^2}{4}+|A_1|\cdot n+\sum_{t = 2}^{4/\epsilon} |A_t| \frac{n}{(t-1)}.
    \end{equation}

    For any $t,$ $\bigcup_{\ell = 1}^t A_\ell = V \setminus \bigcup_{i \in [k]} C_t(I_i),$ and so \eqref{eqn:containers-union} implies that $\sum_{\ell = 1}^{t} |A_\ell| \leq \frac{t \epsilon n}{4\ln(1/\epsilon)}.$ In the sum \eqref{eqn:sum-edges}, the contribution from $|A_t|$ goes down as $t$ increases, and so the sum is maximized when $|A_t|=\frac{\epsilon n}{4\ln(1/\epsilon)}$ for all $t.$ Hence, the sum of the edges in each of the sets $V_1, \dots, V_k$ can be upper bounded by
    \[\frac{\epsilon n^2}{4}+\frac{\epsilon n^2}{4 \ln(1/\epsilon)} + \frac{\epsilon n^2}{4 \ln(1/\epsilon)}\sum_{t=2}^{4/\epsilon} \frac{1}{t-1} \leq \frac{\epsilon n^2}{4}+ \frac{\epsilon n^2}{4 \ln(1/\epsilon)}\left(\ln(4/\epsilon)+2\right) < \epsilon n^2,\]
    where the first inequality uses the upper bound $H(m) \le \ln(m) + 1$ on the harmonic series and the second inequality uses the bound $\epsilon < e^{-2}$ that we can apply without loss of generality. This is a contradiction with the fact that $G$ is $\epsilon$-far from $k$-colorable.
\end{proof}

\begin{restatable}[Graph Container Lemma II]{lemma}{GCLkcolNew}
    \label{lem:GCL-kcolNew}
    Let $G$ be $\epsilon$-far from $k$-colorable.
    Then there exists a collection $\mathcal{F} \subseteq (2^V)^k$ of sequences of fingerprints and a container function $\mathcal{C} : \mathcal{F} \rightarrow 2^V$ that satisfy the following two properties.
    \begin{enumerate}
        \item For every set $U \subseteq V$ such that $G[U]$ is $k$-colorable and $|U| \geq 4k/\epsilon,$ there is a sequence of fingerprints $F=(T_1,\dots,T_k) \in \mathcal{F}$ such that $\bigcup_{i \in [k]} T_i \subseteq U \subseteq \mathcal{C}(F).$
        \item For every sequence of fingerprints $F=(T_1,\dots,T_k) \in \mathcal{F},$ $|T_i| \leq \frac{4}{\epsilon}$ for every $i \in [k],$ and \[|\mathcal{C}(F)| \leq \left( 1 - \frac{\epsilon}{4\ln (\frac 1\epsilon)}\cdot \max_{i \in [k]} |T_i| \right)n.\]
    \end{enumerate}
\end{restatable}
\begin{proof}
    For any $U \subseteq V$ such that $G[U]$ is $k$-colorable, let $\mathcal{I}(U)=(I_1,\dots,I_k)$ be an arbitrary partitioning of $U$ into $k$ independent sets (since $G[U]$ is $k$-colorable at least one such partitioning exists) and let $t_{\mathcal{I}(U)}$ denote the index given in \Cref{lem:GCL-kcol} with the desired container bounds.
    Let \[\mathcal{F}=\{(F_{t_{\mathcal{I}(U)}}(I_1),\dots,F_{t_{\mathcal{I}(U)}}(I_k)) : U\subseteq V \textrm{ is $k$-colorable and } |U| \geq 4k/\epsilon \},\] and let the container function $\mathcal{C}: \mathcal{F} \rightarrow 2^V$ be the function that takes a sequence of fingerprints $F = (T_1,\dots,T_k) \in \mathcal{F}$ and returns $\bigcup_{i \in [k]} C_{\max_{i \in [k]}|T_i|}(T_i),$ where $C_t(\cdot)$ and $F_t(\cdot)$ are the functions defined in \Cref{alg:FingerprintContainer}.
    First observe that for any $U \subseteq V$ such that $G[U]$ is $k$-colorable, $\max_{i \in [k]} |F_{t_{\mathcal{I}(U)}}(I_i)| \leq t_{\mathcal{I}(U)}.$
    Hence, by the basic properties of containers and \Cref{prop:container-closure}, we have that
    \[\bigcup_{i \in [k]} F_{t_{\mathcal{I}(U)}}(I_i) \subseteq U \subseteq \bigcup_{i \in [k]} C_{t_{\mathcal{I}(U)}}(I_i) = \bigcup_{i \in [k]} C_{t_{\mathcal{I}(U)}}(F_{t_{\mathcal{I}(U)}}(I_i)) \subseteq \mathcal{C}(F_{t_{\mathcal{I}(U)}}(I_1),\dots,F_{t_{\mathcal{I}(U)}}(I_k)),\]
    which proves the first conclusion of the lemma.

    We now show the desired upper bounds on the size of every $|T_i|$ for each $F=(T_1,\dots,T_k) \in \mathcal{F}$ and the size of the associated container $\mathcal{C}(F).$
    For any $U \subseteq V$ such that $G[U]$ is $k$-colorable and $|U| \geq 4k/\epsilon,$ we have that, for every $i \in [k],$ $|F_{t_{\mathcal{I}(U)}}(I_i)| \leq t_{\mathcal{I}(U)},$ and by the upper bound on $t_{\mathcal{I}(U)}$ from \Cref{lem:GCL-kcol} we get the desired upper bound on $|F_{t_{\mathcal{I}(U)}}(I_i)|.$
    Furthermore, observe that $\max_{i \in [k]} |F_{t_{\mathcal{I}(U)}}(I_i)|=t_{\mathcal{I}(U)}$ because $\max_{i \in [k]} |I_i| \geq |U|/k \geq 4/\epsilon,$ and so
    \[
    \mathcal{C}(F_{t_{\mathcal{I}(U)}}(I_1),\dots,F_{t_{\mathcal{I}(U)}}(I_k)) = \bigcup_{i \in [k]} C_{\max_{i \in [k]}|F_{t_{\mathcal{I}(U)}}(I_i)|}(F_{t_{\mathcal{I}(U)}}(I_i)) = \bigcup_{i \in [k]} C_{t_{\mathcal{I}(U)}}(F_{t_{\mathcal{I}(U)}}(I_i)).
    \]
    By \Cref{prop:container-closure} this is equal to $\bigcup_{i \in [k]} C_{t_{\mathcal{I}(U)}}(I_i),$ and using the upper bound from \Cref{lem:GCL-kcol} completes the upper bound on the size of $\mathcal{C}(F_{t_{\mathcal{I}(U)}}(I_1),\dots,F_{t_{\mathcal{I}(U)}}(I_k)).$
\end{proof}

With the above in mind, we are now ready to prove the main statement:

\begin{proof}
Let $S$ be a random set of $s = c\frac{k}{\epsilon} \ln^2\left(\frac{1}{\epsilon}\right)$ vertices drawn uniformly at random from $V$ without replacement, where $c$ is a large enough constant. The tester accepts a graph $G$ if and only if $G[S]$ is $k$-colorable. When $G$ is $k$-colorable, then $G[S]$ is also $k$-colorable so the tester always accepts. 
In the remainder of the proof, we upper bound the probability that $G[S]$ is $k$-colorable when $G$ is $\epsilon$-far from $k$-colorable.

Consider the collection of sequences of fingerprints $\mathcal{F}$ and the container function $\mathcal{C} \colon \mathcal{F} \rightarrow 2^V$ from \Cref{lem:GCL-kcolNew}.
For every set $U \subseteq V$ for which $G[U]$ is $k$-colorable and $|U| \geq 4k/\epsilon$, there exists $F=(T_1,\dots,T_k) \in \mathcal{F}$ such that $\bigcup_{i \in [k]} T_i \subseteq U \subseteq \mathcal{C}(F).$
Hence, $G[S]$ is $k$-colorable only when there exists $F=(T_1,\dots,T_k) \in \mathcal{F}$ such that $S \subseteq \mathcal{C}(F)$ and $S$ contains $\bigcup_{i \in [k]}T_i.$
In other words, the probability that $G[S]$ is $k$-colorable is at most
\[\sum_{F=(T_1,\dots,T_k) \in \mathcal{F}} \Pr\left[\bigcup_{i \in [k]} T_i \subseteq S\right] \cdot \Pr\left[S \subseteq \mathcal{C}(F) ~\bigg|~ \bigcup_{i \in [k]} T_i \subseteq S\right].\]

Fix $F=(T_1,\dots,T_k) \in \mathcal{F}$ and let $t = \big| \bigcup_{i \in [k]} T_i \big|$.
The probability that $S$ contains $\bigcup_{i \in [k]}T_i$ is at most
\[\frac{\binom{n-t}{s-t}}{\binom{n}{s}} = \frac{\binom{s}{t}}{\binom{n}{t}},\]
because there are at most $\binom{n}{s}$ ways to choose $S,$ and $\binom{n-t}{s-t}$ ways to choose an $S$ that includes the vertices in $F.$
By the upper bound on $|\mathcal{C}(F)|$ in \Cref{lem:GCL-kcolNew}, the probability that $S \subseteq \mathcal{C}(F)$ conditioned on the fact that $S$ contains $\bigcup_{i \in [k]}T_i,$ can be upper bounded by $ \left( 1 - \frac{\epsilon}{4\ln (1/\epsilon)} \cdot \max_{i \in [k]} |T_i|\right)^{s-t}$.
Hence, the probability above can be upper bounded by
\[
    \sum_{t=1}^{4k/\epsilon} ~\sum_{\substack{F=(T_1,\dots,T_k) \in \mathcal{F}\\ | \bigcup_{i \in [k]} T_i | = t}} \frac{\binom{s}{t}}{\binom{n}{t}} \cdot \left( 1 - \frac{\epsilon}{4\ln (1/\epsilon)} \cdot \max_{i \in [k]} |T_i|\right)^{s-t}
    \leq \sum_{t=1}^{4k/\epsilon} k^t \binom{s}{t} \cdot \left( 1 - \frac{\epsilon}{4\ln (1/\epsilon)} \cdot \frac{t}{k}\right)^{s-t},
\]
where the inequality uses that $\max_{i \in [k]} |T_i| \geq \frac{t}{k}$ and that for any $t$ there are at most $\binom{n}{t} \cdot k^t$ ways to choose a sequence of fingerprints $F = (T_1,\dots,T_k)$ with $\big| \bigcup_{i \in [k]} T_i \big| = t.$
Finally, using that $s > 2t$ and that $\binom{s}{t} \leq s^t,$ this can be upper bounded by
\[\sum_{t=1}^{4k/\epsilon} k^t s^t \cdot \left( 1 - \frac{\epsilon}{4\ln (1/\epsilon)} \cdot \frac{t}{k}\right)^{s/2} \le \sum_{t=1}^{4k/\epsilon} \exp\left(t \ln(s k) - \frac{\epsilon t s}{8k\ln (1/\epsilon)}\right) < 1/3,\]
where the inequality uses the facts that $s = c\frac{k}{\epsilon} \ln^2\left(\frac{1}{\epsilon}\right)$ for a large enough constant $c$ and that the problem is non-trivial only when $\epsilon < 1/k$ and $\ln(\frac k\epsilon) \le \ln\frac1{\epsilon^2} = 2\ln \frac 1\epsilon$ in this regime.
\end{proof}
